    ("SELECT HEX(REVERSE(_gb18030 X'418130FE3942')) AS h,CHAR_LENGTH(_gb18030 X'418130FE3942') AS n,HEX(LEFT(_gb18030 X'418130FE3942',2)) AS l,HEX(SUBSTRING(_gb18030 X'418130FE3942',2,1)) AS s", 'h\tn\tl\ts\n428130FE3941\t3\t418130FE39\t8130FE39\n'),
